import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    nums = [int(x) for x in data[1:1+n]]
    trie = {}
    for x in nums:
        node = trie
        for i in range(30, -1, -1):
            b = (x >> i) & 1
            node = node.setdefault(b, {})
    max_xor = 0
    for x in nums:
        node = trie
        cur = 0
        for i in range(30, -1, -1):
            b = (x >> i) & 1
            opp = 1 - b
            if opp in node:
                cur |= (1 << i)
                node = node[opp]
            else:
                node = node[b]
        max_xor = max(max_xor, cur)
    print(max_xor)
